// Interface defines the contract — closed for modification
interface PaymentProcessor {
    void processPayment(BigDecimal amount);
}

// Each payment method is a separate class — open for extension
class CreditCardProcessor implements PaymentProcessor {
    public void processPayment(BigDecimal amount) {
        System.out.println("Processing credit card payment: " + amount);
        // credit card logic here
    }
}

class UpiProcessor implements PaymentProcessor {
    public void processPayment(BigDecimal amount) {
        System.out.println("Processing UPI payment: " + amount);
        // UPI logic here
    }
}

// New payment method? Just add a new class — no changes to existing code
class WalletProcessor implements PaymentProcessor {
    public void processPayment(BigDecimal amount) {
        System.out.println("Processing wallet payment: " + amount);
    }
}

// Consumer depends on the interface, not implementations
@Service
class OrderService {
    private final PaymentProcessor processor;

    public OrderService(PaymentProcessor processor) {
        this.processor = processor; // injected by Spring
    }

    public void checkout(BigDecimal total) {
        processor.processPayment(total); // works with any implementation
    }
}

// Step 1: Define the interface for varying behavior
interface NotificationService {
    void send(String recipient, String message);
}

// Step 2: Create implementations for each variant
@Service
class EmailNotificationService implements NotificationService {
    public void send(String recipient, String message) {
        System.out.println("Sending email to " + recipient + ": " + message);
        // SMTP logic here
    }
}

@Service
class SmsNotificationService implements NotificationService {
    public void send(String recipient, String message) {
        System.out.println("Sending SMS to " + recipient + ": " + message);
        // SMS gateway logic here
    }
}

// Step 3: New requirement? Add a new class — no changes to existing code
@Service
class PushNotificationService implements NotificationService {
    public void send(String recipient, String message) {
        System.out.println("Sending push to " + recipient + ": " + message);
    }
}

// Step 4: Consumer depends on the interface
@RestController
class OrderController {
    private final NotificationService notificationService;

    // Spring injects the implementation based on config
    public OrderController(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    @PostMapping("/orders")
    public void createOrder(@RequestBody Order order) {
        // business logic
        notificationService.send(order.customerEmail(), "Order confirmed"); // works with any impl
    }
}

// BEFORE: OCP violation — if-else that grows with every new shape
class AreaCalculator {
    public double calculateArea(Object shape, String type) {
        if (type.equals("CIRCLE")) {
            Circle c = (Circle) shape;
            return Math.PI * c.radius * c.radius;
        } else if (type.equals("RECTANGLE")) {
            Rectangle r = (Rectangle) shape;
            return r.width * r.height;
        } else if (type.equals("TRIANGLE")) { // new type = modify this method
            Triangle t = (Triangle) shape;
            return 0.5 * t.base * t.height;
        }
        throw new IllegalArgumentException("Unknown shape");
    }
}

// AFTER: OCP compliant — polymorphism replaces the if-else
interface Shape {
    double calculateArea();
}

class Circle implements Shape {
    private final double radius;
    public Circle(double radius) { this.radius = radius; }
    public double calculateArea() {
        return Math.PI * radius * radius; // behavior in the class
    }
}

class Rectangle implements Shape {
    private final double width, height;
    public Rectangle(double width, double height) { this.width = width; this.height = height; }
    public double calculateArea() { return width * height; }
}

// Adding a new shape? Just create a new class — no changes to existing code
class Triangle implements Shape {
    private final double base, height;
    public Triangle(double base, double height) { this.base = base; this.height = height; }
    public double calculateArea() { return 0.5 * base * height; }
}

// Consumer code is clean and extensible
class AreaService {
    public void printArea(Shape shape) {
        System.out.println("Area: " + shape.calculateArea()); // works with any shape
    }
}

// 1. STRATEGY: swap algorithms via interface
interface DiscountStrategy {
    BigDecimal applyDiscount(BigDecimal price);
}
class SeasonalDiscount implements DiscountStrategy {
    public BigDecimal applyDiscount(BigDecimal price) {
        return price.multiply(BigDecimal.valueOf(0.9)); // 10% off
    }
}
class LoyaltyDiscount implements DiscountStrategy {
    public BigDecimal applyDiscount(BigDecimal price) {
        return price.multiply(BigDecimal.valueOf(0.85)); // 15% off
    }
}

// 2. TEMPLATE METHOD: define structure, vary steps
abstract class ReportGenerator {
    public final void generate() { // final = structure is fixed
        fetchData();
        formatData();
        exportReport();
    }
    protected abstract void fetchData(); // subclasses implement
    protected abstract void formatData();
    private void exportReport() { System.out.println("Exporting..."); }
}
class PdfReportGenerator extends ReportGenerator {
    protected void fetchData() { System.out.println("Fetch for PDF"); }
    protected void formatData() { System.out.println("Format as PDF"); }
}

// 3. DECORATOR: add behavior by wrapping
interface Coffee {
    String getDescription();
    double getCost();
}
class SimpleCoffee implements Coffee {
    public String getDescription() { return "Simple coffee"; }
    public double getCost() { return 5.0; }
}
class MilkDecorator implements Coffee {
    private final Coffee coffee;
    public MilkDecorator(Coffee coffee) { this.coffee = coffee; }
    public String getDescription() { return coffee.getDescription() + ", milk"; }
    public double getCost() { return coffee.getCost() + 1.5; }
}

// 4. FACTORY: create objects without hardcoding types
interface Vehicle { void drive(); }
class Car implements Vehicle { public void drive() { System.out.println("Driving car"); } }
class Bike implements Vehicle { public void drive() { System.out.println("Riding bike"); } }
class VehicleFactory {
    public static Vehicle create(String type) {
        return switch (type) {
            case "CAR" -> new Car();
            case "BIKE" -> new Bike();
            default -> throw new IllegalArgumentException("Unknown type");
        };
    }
}

// CASE 1: Bug fix — modifying existing code is correct
@Service
class OrderService {
    public BigDecimal calculateTotal(Order order) {
        var subtotal = order.items().stream()
            .map(item -> item.price().multiply(BigDecimal.valueOf(item.quantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        // BUG FIX: was missing tax calculation
        var tax = subtotal.multiply(BigDecimal.valueOf(0.18)); // add 18% tax
        return subtotal.add(tax);
    }
}

// CASE 2: New feature — adding new code, not modifying existing
interface ShippingCalculator {
    BigDecimal calculateShipping(Order order);
}

class StandardShipping implements ShippingCalculator {
    public BigDecimal calculateShipping(Order order) {
        return BigDecimal.valueOf(50); // flat rate
    }
}

// New requirement: express shipping — add new class, don't modify StandardShipping
class ExpressShipping implements ShippingCalculator {
    public BigDecimal calculateShipping(Order order) {
        return BigDecimal.valueOf(150); // higher rate
    }
}

@Service
class CheckoutService {
    private final ShippingCalculator shippingCalculator;

    public CheckoutService(ShippingCalculator shippingCalculator) {
        this.shippingCalculator = shippingCalculator; // injected
    }

    public BigDecimal calculateFinalPrice(Order order, BigDecimal orderTotal) {
        var shipping = shippingCalculator.calculateShipping(order);
        return orderTotal.add(shipping); // existing logic unchanged
    }
}

